import { Component, OnInit, Signal, ChangeDetectionStrategy } from '@angular/core';
import { Router } from '@angular/router';
import { take } from 'rxjs';
import { Campaign } from '../interfaces';
import { UserService } from '../services/user.service';
import { AdminDashboardService } from './admin-dashboard.service';
/**
 * this component is the first screen you see after login.
 * you get the exisisting campaigns and can edit or see details of them.
 * you can create a new campaign too.
 */
@Component({
    selector: 'pgt-admin-dashboard',
    templateUrl: './admin-dashboard.component.html',
    styleUrls: ['./admin-dashboard.component.css', '../app.component.css'],
    changeDetection: ChangeDetectionStrategy.Eager,
    standalone: false
})
export class AdminDashboardComponent implements OnInit {
  // a behavior subject that stores all the campaigns of the user
  campaigns: Signal<Campaign[]> = this.adminDashboardService.campaigns;

  constructor(
    private userService: UserService,
    private router: Router,
    private adminDashboardService: AdminDashboardService
  ) {}

  /**
   * upon initialization, it gets the all the campaigns of the user, that just logged in.
   */
  ngOnInit(): void {
    this.userService
      .getUser()
      .pipe(take(1))
      .subscribe(() => {
        this.adminDashboardService.reloadCampaigns();
      });
  }

  onReloadEvent(event: any) {
    this.adminDashboardService.reloadCampaigns();
  }

  createCampaign() {
    this.router.navigate(['/create-campaign/']);
  }
}

import { Injectable, WritableSignal, signal } from '@angular/core';
import { Campaign } from '../interfaces';
import { PGTService } from '../services/pgt.service';
import { CampaignService } from '../services/campaign.service';
import { SnackBarService } from '../services/snack-bar.service';
import { Router } from '@angular/router';
import { HttpErrorResponse } from '@angular/common/http';

@Injectable({
  providedIn: 'root',
})
export class AdminDashboardService {
  campaigns: WritableSignal<Campaign[]> = signal([]);

  constructor(
    private pgtService: PGTService,
    private campaignService: CampaignService,
    private snackBarService: SnackBarService,
    private router: Router
  ) {}

  reloadCampaigns() {
    this.pgtService.getCampaignsByUser().subscribe({
      next: (campaigns: Campaign[]) => {
        let cleanCampaigns = [];
        for (let campaign of campaigns) {
          cleanCampaigns.push(
            this.campaignService.cleanupCampaignData(campaign)
          );
        }
        // the campaigns are sorted by creation date descending
        cleanCampaigns.reverse();
        cleanCampaigns = cleanCampaigns.sort(
          (campaignA, campaignB) =>
            campaignB.creationDate.getTime() - campaignA.creationDate.getTime()
        );

        this.campaigns.set(cleanCampaigns);
      },
      error: (error: HttpErrorResponse) => {
        this.snackBarService.openErrorBar(error);
        this.router.navigate(['/login']);
      },
    });
  }
}

