import { Component, Input, OnInit, ChangeDetectionStrategy } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Campaign, CampaignStatus, Criteria } from 'src/app/interfaces';
import { CampaignService } from '../../services/campaign.service';
import { CreateCampaignService } from '../create-campaign.service';
/**
 * This is a child component of the create campaign component
 * It handles displaying all data regarding criteria
 */
@Component({
    selector: 'pgt-criteria',
    templateUrl: './criteria.component.html',
    styleUrls: ['../../app.component.css', './criteria.component.css'],
    changeDetection: ChangeDetectionStrategy.Eager,
    standalone: false
})
export class CriteriaComponent implements OnInit {
  criteriaForm: FormGroup;
  @Input('campaign') campaign: Campaign;
  @Input('campaignStatus') campaignStatus: CampaignStatus;

  constructor(
    private formBuilder: FormBuilder,
    private createCampaignService: CreateCampaignService,
    private campaignService: CampaignService
  ) {}

  ngOnInit(): void {
    // creating the form for the criteria
    this.criteriaForm = this.formBuilder.group({
      criteriaName: [, Validators.required],
      criteriaWeight: [, [Validators.required, Validators.min(0)]],
    });

    if (this.campaignStatus != 'erstellt') this.criteriaForm.disable();
  }

  /**
   * adds a new criteria to the campaign
   * @param criteriaForm used to get the values entered by the user
   */
  addCriteria(criteriaForm: FormGroup) {
    if (criteriaForm.valid) {
      const criteria = this.campaignService.criteriaConstructor(
        criteriaForm.value.criteriaName,
        criteriaForm.value.criteriaWeight
      );
      this.createCampaignService.addCriteria(this.campaign, criteria);
      criteriaForm.reset();
    } else {
      criteriaForm.markAllAsTouched();
    }
  }

  removeCriteria(criteria: Criteria) {
    this.createCampaignService.removeCriteria(this.campaign, criteria);
  }
}

import { TestBed } from '@angular/core/testing';

import { CsvService } from './csv.service';
import { CampaignService } from '../services/campaign.service';

describe('CsvService', () => {
  let service: CsvService;
  let campaignService: CampaignService;
  let campaignServiceMock: Partial<CampaignService>;

  beforeEach(() => {
    // Create mock implementations for the campaignService methods
    campaignServiceMock = {
      groupConstructor: jest.fn().mockReturnValue({
        groupId: 1,
        number: 1,
        peers: [],
        gradings: [],
        completed: false,
        comments: [],
      }),
      addPeer: jest.fn(),
      peerConstructor: jest.fn().mockReturnValue({
        peerId: 1,
        firstName: 'John',
        lastName: 'Doe',
        matriculationNumber: '35-456-581',
        email: 'john.doe@example.com',
      }),
      autoNumberGroups: jest.fn(),
    };

    TestBed.configureTestingModule({
      providers: [
        CsvService,
        {
          provide: CampaignService,
          useValue: campaignServiceMock,
        },
      ],
    });
    service = TestBed.inject(CsvService);
    campaignService = TestBed.inject(CampaignService);

    // Resetting signals before each test
    service.csvErrors.set([]);
  });

  it('should handle an empty CSV string', () => {
    const csv = '';
    const result = service.generateGroupsByCSV(csv);

    expect(result).toEqual([]); // No groups generated
    expect(service.csvErrors()).toContain(
      $localize`Ist das CSV gemäss der Vorlage aufgebaut?`
    );
  });

  it('should handle a CSV missing required columns', () => {
    const csv = 'Nachname;Vorname;E-Mail\nDoe;John;john.doe@example.com'; // No group number
    const result = service.generateGroupsByCSV(csv);

    expect(result).toEqual([]);
    expect(service.csvErrors()).toContain(
      $localize`Ist das CSV gemäss der Vorlage aufgebaut?`
    );
  });

  it('should handle a CSV missing optional Matrikel-Nr', () => {
    const csv =
      'Nachname;Vorname;E-Mail;Gruppennummer\nDoe;John;john.doe@example.com;1';
    const result = service.generateGroupsByCSV(csv);

    expect(result.length).toBe(1); // One group should be generated
    expect(service.csvErrors()).toEqual([]); // No errors
  });

  it('should handle CSV with "Mail" and "Gruppe" for email and group number columns', () => {
    const csv = 'Nachname;Vorname;Mail;Gruppe\nDoe;John;john.doe@example.com;1';
    const result = service.generateGroupsByCSV(csv);

    expect(result.length).toBe(1); // One group generated
    expect(service.csvErrors()).toEqual([]); // No errors
  });

  it('should handle a CSV with non-standard column order', () => {
    const csv =
      'Vorname;Nachname;E-Mail;Gruppennummer\nJohn;Doe;john.doe@example.com;1';
    const result = service.generateGroupsByCSV(csv);

    expect(result.length).toBe(1); // One group generated
    expect(service.csvErrors()).toEqual([]); // No errors
  });

  it('should ignore extra columns like "Geburtsdatum"', () => {
    const csv =
      'Nachname;Vorname;E-Mail;Gruppennummer;Geburtsdatum\nDoe;John;john.doe@example.com;1;01-01-1990';
    const result = service.generateGroupsByCSV(csv);

    expect(result.length).toBe(1); // One group generated
    expect(service.csvErrors()).toEqual([]); // No errors
  });

  it('should add peers to the same group for duplicate group numbers', () => {
    const csv = `name;vorname;mail;gruppe
    Doe;John;john@example.com;1
    Smith;Jane;jane@example.com;1`;

    service.generateGroupsByCSV(csv);

    expect(service.csvErrors()).toHaveLength(0);
    const groups = service.generateGroupsByCSV(csv);
    expect(groups).toHaveLength(1); // Only one group should exist
  });

  it('should log an error for invalid email addresses', () => {
    const csv = `name;vorname;mail;gruppe
    Doe;John;john@example;1`;

    service.generateGroupsByCSV(csv);

    expect(service.csvErrors()).toContain(
      'Zeile 2 (Doe | John | john@example | 1): invalide E-mail Adresse.'
    );
  });

  it('should log an error for empty required fields in a row', () => {
    const csv = `name;vorname;mail;gruppe
    Doe;;john@example.com;1`;

    service.generateGroupsByCSV(csv);

    expect(service.csvErrors()).toContain(
      'Zeile 2 (Doe |  | john@example.com | 1): kein Vorname.'
    );
  });

  it('should log an error for non-numeric group numbers', () => {
    const csv = `name;vorname;mail;gruppe
    Doe;John;john@example.com;abc`;

    service.generateGroupsByCSV(csv);

    expect(service.csvErrors()).toContain(
      'Zeile 2 (Doe | John | john@example.com | abc): invalide Gruppennummer.'
    );
  });

  it('should correctly parse the CSV when columns are not in the usual order', () => {
    const csv = `vorname;mail;gruppe;name
    John;john@example.com;1;Doe`;

    service.generateGroupsByCSV(csv);

    expect(service.csvErrors()).toHaveLength(0); // No errors should be reported
    const groups = service.generateGroupsByCSV(csv);
    expect(groups).toHaveLength(1); // There should be one group
  });
});

import { Injectable, WritableSignal, inject, signal } from '@angular/core';
import { Group } from '../interfaces';
import { CampaignService } from '../services/campaign.service';

interface LineValidation {
  valid: boolean;
  invalidMessage?: string;
}

/**
 * This service is used when importing CSV data
 */
@Injectable({
  providedIn: 'root',
})
export class CsvService {
  campaignService: CampaignService = inject(CampaignService);

  csvErrors: WritableSignal<string[]> = signal([]);

  /**
   * this method generates the groups from the CSV
   * @param csv the CSV as a string
   */
  generateGroupsByCSV(csv: string): Group[] {
    this.csvErrors.set([]);

    let groups: Group[] = [];
    let lines = csv.split(/\r?\n/);

    const firstLine: string[] = this.splitLine(lines[0]).map(
      (colName: string) => colName.toLowerCase().trim()
    );

    const lastNameIndex = this.findColumnIndex(
      firstLine,
      (colName) => colName.includes('name') && !colName.includes('vorname')
    );
    const firstNameIndex = this.findColumnIndex(firstLine, (colName) =>
      colName.includes('vorname')
    );
    const eMailIndex = this.findColumnIndex(firstLine, (colName) =>
      colName.includes('mail')
    );
    const groupIndex = this.findColumnIndex(firstLine, (colName) =>
      colName.includes('gruppe')
    );
    const matriculationNumberIndex = this.findColumnIndex(
      firstLine,
      (colName) => colName.includes('matrikel')
    );

    if (
      lastNameIndex == -1 ||
      firstNameIndex == -1 ||
      eMailIndex == -1 ||
      groupIndex == -1
    ) {
      this.addError($localize`Ist das CSV gemäss der Vorlage aufgebaut?`);
      return [];
    }

    for (let [index, line] of lines.entries()) {
      // skipping the first line and empty lines
      if (index == 0 || line == '') {
        continue;
      }

      const splittedLine: string[] = this.splitLine(line).map((cell: string) =>
        cell.trim()
      );

      // storing the values
      const lastName = splittedLine[lastNameIndex];
      const firstName = splittedLine[firstNameIndex];
      const email = splittedLine[eMailIndex];
      const groupNumberString: string = splittedLine[groupIndex];
      const matriculationNumber =
        matriculationNumberIndex >= 0
          ? splittedLine[matriculationNumberIndex]
          : '';

      // checking if the values are valid and storing them in a group
      // else pushing this line to the errors to display
      const lineValidation: LineValidation = this.validateLine(
        lastName,
        firstName,
        email,
        groupNumberString
      );

      if (!lineValidation.valid) {
        this.addError(
          $localize`Zeile` +
            ` ${index + 1} (${splittedLine.join(' | ')}): ${
              lineValidation.invalidMessage
            }`
        );
      }

      const groupNumber: number = Number(groupNumberString);

      let foundGroup = groups.find((gr) => gr.number == groupNumber);

      if (!foundGroup) {
        foundGroup = this.campaignService.groupConstructor(groupNumber);
        groups.push(foundGroup);
      }

      this.campaignService.addPeer(
        foundGroup,
        this.campaignService.peerConstructor(
          firstName,
          lastName,
          email,
          matriculationNumber
        )
      );
    }

    groups = this.updateGroupNumbers(groups);

    return groups;
  }

  private findColumnIndex(
    firstLine: string[],
    searchFunction: (colName: string) => boolean
  ): number {
    return firstLine.findIndex((colName: string) => searchFunction(colName));
  }

  private addError(errorMessage: string) {
    this.csvErrors.update((value: string[]) => [...value, errorMessage]);
  }

  private splitLine(line: string): string[] {
    // checking for semicolons, commas or tabs as separators
    let semicolonSplittedLine = line.split(';');
    let commaSplittedLine = line.split(',');
    let tabSplittedLine = line.split('\t');

    if (
      semicolonSplittedLine.length > commaSplittedLine.length &&
      semicolonSplittedLine.length > tabSplittedLine.length
    ) {
      return semicolonSplittedLine;
    }

    if (commaSplittedLine.length > tabSplittedLine.length) {
      return commaSplittedLine;
    }

    return tabSplittedLine;
  }

  private validateLine(
    lastName: string,
    firstName: string,
    email: string,
    groupNumber: string
  ): LineValidation {
    const lastNameValid = lastName.length !== 0;
    const firstNameValid = firstName.length !== 0;
    const emailValid =
      email.match(
        "^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9-]+(?:\\.[a-zA-Z0-9-]+)*\\.[a-zA-Z]{2,5}$"
      ) != null;
    const groupNumberValid = groupNumber.match('^\\d+$') != null;

    let invalidMessages: string[] = [];

    if (!lastNameValid) invalidMessages.push($localize`kein Nachname`);
    if (!firstNameValid) invalidMessages.push($localize`kein Vorname`);
    if (!emailValid) invalidMessages.push($localize`invalide E-mail Adresse`);
    if (!groupNumberValid)
      invalidMessages.push($localize`invalide Gruppennummer`);

    return {
      valid: lastNameValid && firstNameValid && emailValid && groupNumberValid,
      invalidMessage: `${invalidMessages.join(', ')}.`,
    };
  }

  private updateGroupNumbers(groups: Group[]): Group[] {
    // sorting according to group number
    const sortedGroups = groups.sort((a, b) => a.number - b.number);
    // find max group number
    const maxGroupNumber = sortedGroups[sortedGroups.length - 1]?.number || 0;

    // autonumbering if max is higher than the number of groups
    // meaning that a group number was missing
    if (maxGroupNumber !== groups.length) {
      this.campaignService.autoNumberGroups(groups);
      this.addError(
        $localize`Hinweis: Die Gruppen wurden beginnend mit Nr. 1 fortlaufend neu nummeriert.`
      );
    }

    return sortedGroups;
  }
}

