import { Injector, Injectable } from '@angular/core';
import { HttpRequest, HttpHandler, HttpEvent, HttpInterceptor, HttpClient, HttpErrorResponse } from '@angular/common/http';
import {
  BehaviorSubject,
  catchError,
  from,
  Observable,
  Subject,
  Subscription,
  switchMap,
  throwError,
} from 'rxjs';
import { TokenService } from '../services/token.service';
import { AuthService } from '../services/auth.service';
import { environment } from '../../environments/environment';

@Injectable()
export class ErrorInterceptor implements HttpInterceptor {
  static accessTokenError: BehaviorSubject<boolean> =
    new BehaviorSubject<boolean>(false);

  constructor(
    private http: HttpClient,
    private tokenService: TokenService,
    private injector: Injector
  ) {}

  intercept(
    request: HttpRequest<unknown>,
    next: HttpHandler
  ): Observable<HttpEvent<unknown>> {
    const isRefresh = request.url.endsWith('auth/refresh');
    const isLogin = request.url.endsWith('auth/login');
    const isRegister = request.url.endsWith('auth/register');
    const isExchange = request.url.endsWith('auth/oidc/exchange');
    const isAuthConfig = request.url.endsWith('auth/config');

    return next.handle(request).pipe(
      catchError((err: HttpErrorResponse) => {
        if (
          err.status === 401 &&
          !isRefresh &&
          !isLogin &&
          !isRegister &&
          !isExchange &&
          !isAuthConfig
        ) {
          const authService = this.injector.get(AuthService);

          // In OIDC mode the PGT access token can be renewed by exchanging a
          // fresh DocPouch token. This needs no extra DocPouch request beyond
          // the one exchange call.
          if (authService.isOidcMode()) {
            return from(authService.renewPgtSession()).pipe(
              switchMap((renewed) =>
                renewed
                  ? next.handle(this.withAccessToken(request))
                  : this.failAuthentication(err)
              ),
              catchError(() => this.failAuthentication(err))
            );
          }

          return this.refreshToken(next, request);
        }
        // this.router.navigate(['/error/' + err.status]);
        return throwError(() => err);
      })
    );
  }

  /**
   * this function handles 401 errors and tries to refresh the access token
   * for multiple 401 errors, the first gets the new tokens and all other wait until the new tokens arrive
   */
  refreshToken(
    next: HttpHandler,
    request: HttpRequest<any>
  ): Observable<HttpEvent<any>> {
    if (!ErrorInterceptor.accessTokenError.getValue()) {
      ErrorInterceptor.accessTokenError.next(true);

      // gets the new tokens
      return this.http.get(environment.api + '/auth/refresh').pipe(
        switchMap((user: any) => {
          // the new refresh token came as cookie, keep the access token
          this.tokenService.setAccessToken(user.accessToken);

          ErrorInterceptor.accessTokenError.next(false);
          // Clone the request with new Access Token
          return next.handle(this.withAccessToken(request));
        }),
        catchError((err: HttpErrorResponse) => {
          // in case even the refresh failed
          ErrorInterceptor.accessTokenError.next(false);
          return this.failAuthentication(err);
        })
      );
    } else {
      // If it's not the first error, it has to wait until the new tokens arrive
      return this.awaitNewTokens().pipe(
        switchMap(() => {
          // Clone the request with new Access Token
          return next.handle(this.withAccessToken(request));
        })
      );
    }
  }

  private withAccessToken(request: HttpRequest<any>): HttpRequest<any> {
    return request.clone({
      setHeaders: {
        Authorization: `Bearer ${this.tokenService.getToken()}`,
      },
    });
  }

  private failAuthentication(err: HttpErrorResponse): Observable<never> {
    this.tokenService.signOut();
    // reloading the location without tokens will fire the auth guard to return to login
    location.reload();
    return throwError(() => err);
  }

  /**
   * lets a request wait until the new access tokens are set
   * @returns
   */
  private awaitNewTokens(): Observable<any> {
    const subject = new Subject<any>();

    const awaitToken: Subscription =
      ErrorInterceptor.accessTokenError.subscribe((error: boolean) => {
        if (!error) {
          subject.next(true);
          awaitToken.unsubscribe();
        }
      });
    return subject.asObservable();
  }
}

import { Inject, Injectable, LOCALE_ID } from '@angular/core';
import { HttpRequest, HttpHandler, HttpEvent, HttpInterceptor } from '@angular/common/http';
import { Observable } from 'rxjs';

@Injectable()
export class LangInterceptor implements HttpInterceptor {
  constructor(@Inject(LOCALE_ID) public currentLocale: string) {}

  intercept(
    request: HttpRequest<unknown>,
    next: HttpHandler
  ): Observable<HttpEvent<unknown>> {
    // Get the desired language from your application (e.g., from a service)
    const lang = this.currentLocale;

    // Clone the request and add the 'lang' header
    const modifiedRequest = request.clone({
      setHeaders: {
        lang: lang,
      },
    });

    // Pass the modified request to the next handler
    return next.handle(modifiedRequest);
  }
}

import { HttpHeaders, HttpRequest } from '@angular/common/http';
import { of } from 'rxjs';
import { environment } from '../../environments/environment';
import { TokenService } from '../services/token.service';
import { MainInterceptor } from './main.interceptor';

describe('MainInterceptor', () => {
  const tokens = new TokenService();
  const interceptor = new MainInterceptor(tokens);

  function send(url: string, headers = new HttpHeaders()) {
    let sent!: HttpRequest<any>;
    interceptor
      .intercept(new HttpRequest('GET', url, { headers }), {
        handle: (r: HttpRequest<any>) => {
          sent = r;
          return of({} as any);
        },
      })
      .subscribe();
    return sent;
  }

  beforeEach(() => tokens.setAccessToken('access'));

  it('sends the access token to the API', () => {
    const r = send(environment.api + '/campaign');
    expect(r.headers.get('Authorization')).toBe('Bearer access');
    expect(r.withCredentials).toBe(false);
  });

  it('auth requests send the refresh cookie (withCredentials)', () => {
    const r = send(environment.api + '/auth/refresh');
    expect(r.withCredentials).toBe(true);
    // the refresh token is never put into a header by JavaScript
    expect(r.headers.get('Authorization')).toBe('Bearer access');
  });

  it('no token and no cookie for other hosts', () => {
    const r = send('https://docpouch.example/api/x');
    expect(r.headers.has('Authorization')).toBe(false);
    expect(r.withCredentials).toBe(false);
  });

  it('skipAuth keeps the DocPouch token for the exchange', () => {
    const r = send(
      environment.api + '/auth/oidc/exchange',
      new HttpHeaders({ Authorization: 'Bearer docpouch', skipAuth: 'true' })
    );
    expect(r.headers.get('Authorization')).toBe('Bearer docpouch');
  });
});

import { Injectable } from '@angular/core';
import { HttpRequest, HttpHandler, HttpEvent, HttpInterceptor } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../../environments/environment';

import { TokenService } from '../services/token.service';
/**
 * The login interceptor sends the JWT with almost every request to the backend.
 */
@Injectable()
export class MainInterceptor implements HttpInterceptor {
  constructor(private tokenService: TokenService) {}

  intercept(
    request: HttpRequest<any>,
    next: HttpHandler
  ): Observable<HttpEvent<any>> {
    // setting up variables
    const token = this.tokenService.getToken();
    const isApiUrl = request.url.startsWith(environment.api);
    const isAuthUrl = isApiUrl && request.url.includes('/auth/');
    const skipAuth = request.headers.has('skipAuth');

    // checking if there is a token and the request goes to the backend
    // skipAuth is used for public requests like the links that peers get
    if (token && isApiUrl && !skipAuth) {
      request = request.clone({
        setHeaders: { Authorization: `Bearer ${token}` },
      });
    }

    // the refresh token is an HttpOnly cookie for <api>/auth/... The browser
    // sends and stores it by itself; withCredentials is needed when the API
    // runs on another port (dev server).
    if (isAuthUrl) {
      request = request.clone({ withCredentials: true });
    }

    // next up is the error interceptor
    return next.handle(request);
  }
}

