import { Injectable } from '@angular/core';
import {
  Campaign,
  CampaignStatus,
  Criteria,
  Grading,
  Group,
  Language,
  Peer,
  PeerComment,
  User,
} from '../interfaces';

/**
 * campaign service handles everything regarding campaign logic
 */
/**
 * Possible rounding steps of the final grade (setting per campaign).
 * Same values as in the backend (calculations.service.ts).
 */
export const GRADE_ROUNDING_STEPS = [0.5, 0.25, 0.1, 1, 0];
export const DEFAULT_GRADE_ROUNDING = 0.5;

/**
 * Rounds to the nearest multiple of `step` (commercial rounding, symmetric
 * around 0). Step 0.5: 4.24 -> 4, 4.25 -> 4.5, 4.75 -> 5, -0.25 -> -0.5.
 * Step 0: 2 decimals. Same function as in the backend.
 */
export function roundToStep(value: number, step: number): number {
  const s = step > 0 ? step : 0.01;
  // the small epsilon avoids errors like 4.7499999999 for 4.75
  const rounded = Math.round(Math.abs(value) / s + 1e-9) * s;
  // remove floating point noise (e.g. 0.30000000000000004)
  const clean = Math.round(rounded * 1e6) / 1e6;
  return clean === 0 ? 0 : Math.sign(value) * clean;
}

/** rounds to half points (Swiss half grades) */
export function roundToHalf(value: number): number {
  return roundToStep(value, 0.5);
}

/** rounding step of a campaign; old data without the field: half grades */
export function gradeRoundingOf(campaign?: { gradeRounding?: number | null }): number {
  const step = campaign?.gradeRounding;
  return typeof step === 'number' && GRADE_ROUNDING_STEPS.includes(step)
    ? step
    : DEFAULT_GRADE_ROUNDING;
}

@Injectable({
  providedIn: 'root',
})
export class CampaignService {
  constructor() {}

  ///////////// campaign

  campaignConstructor(
    name: string,
    maxPoints: number,
    language: Language,
    allowCommentsForPeers: boolean = true,
    creationDate: Date = new Date(),
    openingDate?: Date,
    closingDate?: Date,
    groups: Group[] = [],
    criteria: Criteria[] = [],
    id: number = 0
  ): Campaign {
    return <Campaign>{
      campaignId: id,
      name: name,
      language: language,
      allowCommentsForPeers: allowCommentsForPeers,
      maxPoints: maxPoints,
      // default: half grades (Swiss grading)
      gradeRounding: DEFAULT_GRADE_ROUNDING,
      creationDate: creationDate,
      openingDate: openingDate,
      closingDate: closingDate,
      groups: groups,
      criteria: criteria,
    };
  }

  cleanupCampaignData(campaign: Campaign): Campaign {
    const { creationDate, openingDate, closingDate, ...rest } = campaign;

    return {
      creationDate: new Date(creationDate),
      openingDate: openingDate ? new Date(openingDate) : undefined,
      closingDate: closingDate ? new Date(closingDate) : undefined,
      ...rest,
    };
  }

  // do not localize
  getCampaignStatus(campaign: Campaign): CampaignStatus {
    if (!campaign.openingDate && !campaign.closingDate) {
      return `erstellt`;
    } else if (campaign.openingDate && !campaign.closingDate) {
      return `läuft`;
    } else {
      return `abgeschlossen`;
    }
  }

  gradingsComplete(campaign: Campaign): boolean {
    for (const group of campaign.groups) {
      if (
        group.gradings.length <
        group.peers.length * group.peers.length * campaign.criteria.length
      )
        return false;
    }
    return true;
  }

  countPeers(campaign: Campaign): number {
    let total = 0;
    for (const group of campaign.groups) {
      total += group.peers.length;
    }
    return total;
  }

  countCompletedPeers(campaign: Campaign): number {
    let total = 0;
    for (const group of campaign.groups) {
      for (const peer of group.peers) {
        const gradings = group.gradings.filter(
          (gr: Grading) => gr.fromPeerId == peer.peerId
        );

        if (gradings.length === campaign.criteria.length * group.peers.length)
          total++;
      }
    }

    return total;
  }

  getCompletionPercentage(campaign: Campaign) {
    return (
      Math.round(
        (1000 * this.countCompletedPeers(campaign)) / this.countPeers(campaign)
      ) / 10
    );
  }

  addGroup(campaign: Campaign, ...groups: Group[]): void {
    for (let group of groups) {
      campaign.groups.push(group);
    }
    this.autoNumberGroups(campaign.groups);
  }

  removeGroup(campaign: Campaign, ...groups: Group[]) {
    for (let groupToDelete of groups) {
      const index = campaign.groups.indexOf(groupToDelete);
      if (index != -1) {
        campaign.groups.splice(index, 1);
      }
    }
    this.autoNumberGroups(campaign.groups);
  }

  /**
   * if a group is added or removed, the groups are automatically numbered
   */
  autoNumberGroups(groups: Group[]): void {
    groups.forEach((group, index) => (group.number = index + 1));
  }

  addCriteria(campaign: Campaign, ...criteria: Criteria[]): void {
    for (let crit of criteria) {
      campaign.criteria.push(crit);
    }
  }

  removeCriteria(campaign: Campaign, ...criteria: Criteria[]): void {
    for (let crit of criteria) {
      const index = campaign.criteria.indexOf(crit, 0);
      if (index > -1) {
        campaign.criteria.splice(index, 1);
      }
    }
  }

  getCriteriaByName(campaign: Campaign, name: string): Criteria {
    for (let criteria of campaign.criteria) {
      if (criteria.name === name) {
        return criteria;
      }
    }
    throw 'criteria ' + name + ' does not exist';
  }

  addGrading(group: Group, grading: Grading): void {
    this.addGradingToGroup(group, grading);
  }

  ///////////// group

  groupConstructor(
    number: number = 0,
    peers: Peer[] = [],
    gradings: Grading[] = [],
    completed: boolean = false,
    comments: PeerComment[] = [],
    id: number = 0
  ): Group {
    return <Group>{
      groupId: id,
      number: number,
      peers: peers,
      gradings: gradings,
      completed: completed,
      comments: comments,
    };
  }

  addPeer(group: Group, ...peers: Peer[]): void {
    for (let peer of peers) {
      group.peers.push(peer);
    }
  }

  removePeerFromGroup(group: Group, ...peers: Peer[]): void {
    for (let peer of peers) {
      const index = group.peers.indexOf(peer, 0);
      if (index > -1) {
        group.peers.splice(index, 1);
      }
    }
  }

  addGradingToGroup(group: Group, grading: Grading): void {
    this.updateExistingGrading(group, grading);
  }

  updateExistingGrading(group: Group, newGrading: Grading): void {
    for (let grading of group.gradings) {
      if (
        newGrading.criteria == grading.criteria &&
        newGrading.fromPeer == grading.fromPeer &&
        newGrading.toPeer == grading.toPeer
      ) {
        grading.points = newGrading.points;
        return;
      }
    }
    group.gradings.push(newGrading);
  }

  getCommentByPeer(group: Group, peer: Peer): PeerComment | null {
    for (let comment of group.comments) {
      if (this.peerEquals(comment.fromPeer, peer)) {
        return comment;
      }
    }
    return null;
  }

  getPeerToPeerGradings(group: Group, fromPeer: Peer, toPeer: Peer): Grading[] {
    return group.gradings.filter((grading: Grading) => {
      return (
        this.peerEquals(grading.toPeer, toPeer) &&
        this.peerEquals(grading.fromPeer, fromPeer)
      );
    });
  }

  getGradingPointsByPeersAndCriteria(
    group: Group,
    fromPeer: Peer,
    toPeer: Peer,
    criteria: Criteria
  ) {
    const grading = group.gradings.find((grading) => {
      return (
        grading.fromPeer.peerId == fromPeer.peerId &&
        grading.toPeer.peerId == toPeer.peerId &&
        grading.criteria.criteriaId == criteria.criteriaId
      );
    });
    if (!grading) return 0;
    return grading.points;
  }

  getGradingsByPeer(group: Group, fromPeer: Peer): Grading[] {
    const gradings = [];
    for (let toPeer of group.peers) {
      gradings.push(...this.getPeerToPeerGradings(group, fromPeer, toPeer));
    }
    return gradings;
  }

  getPeerToPeerAverage(group: Group, fromPeer: Peer, toPeer: Peer): number {
    const gradings = this.getPeerToPeerGradings(group, fromPeer, toPeer);
    if (gradings.length == 0) {
      return 0;
    } else {
      let sum = 0;
      let count = 0;
      for (let grading of gradings) {
        sum += grading.points * grading.criteria.weight;
        count += grading.criteria.weight;
      }
      return Math.round((sum / count) * 100) / 100;
    }
  }

  getPeersSelfAverage(group: Group, peer: Peer): number {
    return this.getPeerToPeerAverage(group, peer, peer);
  }

  getPeersThirdPartyAverageByCriteria(
    criteria: Criteria,
    group: Group,
    peer: Peer
  ): number {
    let sum = 0;
    let count = 0;
    const filteredGradings = group.gradings.filter(
      (grading) =>
        grading.criteria.criteriaId == criteria.criteriaId &&
        grading.toPeer.peerId == peer.peerId &&
        grading.fromPeer.peerId != peer.peerId
    );
    for (let grading of filteredGradings) {
      sum += grading.points;
      count++;
    }
    if (count == 0) {
      return 0;
    }
    return Math.round((sum / count) * 100) / 100;
  }

  getPeersThirdPartyAverage(group: Group, peer: Peer): number {
    let sum = 0;
    let count = 0;
    const filteredGradings = group.gradings.filter(
      (grading) =>
        grading.toPeer.peerId == peer.peerId &&
        grading.fromPeer.peerId != peer.peerId
    );
    for (let grading of filteredGradings) {
      sum += grading.points * grading.criteria.weight;
      count += grading.criteria.weight;
    }
    if (count == 0) {
      return 0;
    }
    return Math.round((sum / count) * 100) / 100;
  }

  /**
   * Deviation of a peer = third-party average - group average, rounded with
   * the rounding step of the campaign (same as the backend).
   */
  getPeerReviewDifference(
    group: Group,
    peer: Peer,
    step: number = DEFAULT_GRADE_ROUNDING
  ): number {
    return roundToStep(
      this.getPeersThirdPartyAverage(group, peer) - this.getGroupAverage(group),
      step
    );
  }

  /**
   * Final grade of a peer = weighted average of the gradings by the others,
   * rounded with the rounding step of the campaign (default: half grades).
   */
  getPeersGrade(campaign: Campaign, group: Group, peer: Peer): number {
    return roundToStep(
      this.getPeersThirdPartyAverage(group, peer),
      gradeRoundingOf(campaign)
    );
  }

  getGroupAverage(group: Group): number {
    let sum = 0;
    let count = 0;
    const filteredGradings = group.gradings.filter(
      (grading) => grading.toPeer.peerId != grading.fromPeer.peerId
    );
    for (let grading of filteredGradings) {
      sum += grading.points * grading.criteria.weight;
      count += grading.criteria.weight;
    }
    if (count == 0) return 0;
    return Math.round((sum / count) * 100) / 100;
  }

  ///////////// peer

  peerConstructor(
    firstName: string,
    lastName: string,
    eMail: string,
    matriculationNumber?: string,
    id: number = 0
  ): Peer {
    return <Peer>{
      peerId: id,
      firstName: firstName,
      lastName: lastName,
      matriculationNumber: matriculationNumber,
      email: eMail,
    };
  }

  peerEquals(peer1: Peer, peer2: Peer): boolean {
    return peer1.peerId == peer2.peerId;
  }

  ///////////// criteria

  criteriaConstructor(name: string, weight: number, id: number = 0): Criteria {
    return <Criteria>{
      criteriaId: id,
      name: name,
      weight: weight,
    };
  }

  ///////////// grading

  gradingConstructor(
    criteria: Criteria,
    from: Peer,
    to: Peer,
    points: number,
    timestamp: Date = new Date(),
    gradingId: number = 0
  ): Grading {
    return <Grading>{
      gradingId: gradingId,
      criteria: criteria,
      fromPeer: from,
      toPeer: to,
      points: points,
      timestamp: timestamp,
    };
  }

  ///////////// peerComment

  peerCommentConstructor(
    fromPeer: Peer,
    toUser: User,
    text: string
  ): PeerComment {
    return <PeerComment>{
      fromPeer,
      toUser,
      text,
    };
  }
}

import { Injectable } from '@angular/core';
import { UserService } from './user.service';
import { Campaign, Grading, MailsSent, PeerComment } from '../interfaces';
import { HttpClient } from '@angular/common/http';
import { environment } from '../../environments/environment';
import { Observable } from 'rxjs';

/**
 * this service handles most of the data transactions between frontend and backend
 */
@Injectable({
  providedIn: 'root',
})
export class PGTService {
  constructor(private http: HttpClient, private userService: UserService) {}

  deleteCampaign(campaign: Campaign) {
    return this.http.delete<Campaign>(
      environment.api + '/campaign/' + campaign.campaignId
    );
  }

  /**
   * this function updates a campaign
   * @param campaign
   * @returns
   */
  updateCampaign(campaign: Campaign) {
    return this.http.post<Campaign>(
      environment.api + '/campaign/update',
      campaign
    );
  }

  /**
   * this function creates a campaign
   * @param campaign
   * @returns
   */
  createCampaign(campaign: Campaign) {
    console.log('createing campaign', campaign);
    return this.http.post<Campaign>(
      environment.api + '/campaign/create',
      campaign
    );
  }

  getCampaignsByUser() {
    return this.http.get<Campaign[]>(environment.api + '/campaign/user');
  }

  getCampaignById(campaignId: number) {
    return this.http.get<Campaign>(environment.api + '/campaign/' + campaignId);
  }

  startCampaign(campaignId: number): Observable<MailsSent> {
    return this.http.get<MailsSent>(
      environment.api + '/campaign/start/' + campaignId
    );
  }

  endCampaign(campaignId: number): Observable<any> {
    return this.http.get<any>(environment.api + '/campaign/end/' + campaignId);
  }

  sendCampaignResults(campaignId: number): Observable<MailsSent> {
    return this.http.get<MailsSent>(
      environment.api + '/campaign/results/' + campaignId
    );
  }

  sendReminderMails(campaignId: number): Observable<MailsSent> {
    return this.http.get<MailsSent>(
      environment.api + '/campaign/reminder-mails/' + campaignId
    );
  }

  addGradingsAndComment(
    url: string,
    data: {
      gradings: Grading[];
      comments: any;
      groupId: number;
    },
  ) {
    return this.http.post(environment.api + '/group/' + url, data, {
      headers: {
        skipAuth: 'true',
      },
    });
  }

  getGroupByLink(url: string) {
    return this.http.get<any>(environment.api + '/group/' + url, {
      headers: {
        skipAuth: 'true',
      },
    });
  }

  /**
   * used to get all data in a single group by the url ending
   * @param url
   * @returns
   */
  getGroupForReview(url: string) {
    return this.http.get<any>(environment.api + '/group/review/' + url, {
      headers: {
        skipAuth: 'true',
      },
    });
  }

  /**
   * uses the url ending to get the specific pdf for a peer
   * @param url
   * @returns
   */
  getReviewPDF(url: string): Observable<Blob> {
    return this.http.get<Blob>(environment.api + '/pdf/review/' + url, {
      responseType: 'blob',
      headers: {
        skipAuth: 'true',
      },
    } as Record<string, unknown>);
  }

  /**
   * uses the url ending to get the specific pdf for a campaign
   * @param campaignId
   * @returns
   */
  getCampaignSummaryPDF(campaignId: number): Observable<Blob> {
    return this.http.get<Blob>(
      environment.api + '/pdf/campaign/' + campaignId,
      {
        responseType: 'blob',
      } as Record<string, unknown>
    );
  }

  /**
   * uses the url ending to get the specific excel for a campaign
   * @param campaignId
   * @returns
   */
  getCampaignSummaryExcel(campaignId: number): any {
    return this.http.get(environment.api + '/excel/' + campaignId, {
      responseType: 'arraybuffer',
    });
  }
}

import { HttpErrorResponse } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { MatSnackBar } from '@angular/material/snack-bar';

@Injectable({
  providedIn: 'root',
})
export class SnackBarService {
  constructor(private snackBar: MatSnackBar) {}

  /**
   * the snackbar is used to show a user that an action has taken place or an error occured
   * shown at the bottom of the screen
   * @param message
   * @param action
   */
  openSnackBar(
    message: string,
    action: string = $localize`Schliessen`,
    duration: number = 15000
  ) {
    this.snackBar.open(message, action, {
      duration: duration,
      panelClass: ['info-snackbar'],
    });
  }

  openErrorBar(
    error: HttpErrorResponse,
    action: string = $localize`Schliessen`,
    duration: number = 15000
  ) {
    let status = error.status;
    let message = error.error.message;
    let text = error.statusText;
    if (status && message) {
      this.openSnackBar(
        $localize`Fehler` + ` ${status}: ${message}`,
        action,
        duration
      );
    } else if (status && text) {
      this.openSnackBar(
        $localize`Fehler` + ` ${status}: ${text}`,
        action,
        duration
      );
    } else {
      this.openSnackBar(
        $localize`Fehler` + ` : ${JSON.stringify(error)}`,
        action,
        duration
      );
    }
  }
}

import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { environment } from '../../environments/environment';
import { User } from '../interfaces';
/**
 * this service handles all things regarding super user functionality
 */
@Injectable({
  providedIn: 'root',
})
export class SuperService {
  constructor(private http: HttpClient) {}

  getAdmins(): Observable<User[]> {
    return this.http.get<User[]>(environment.api + '/user/admins');
  }

  createAdmin(admin: {
    email: string;
    firstName: string;
    lastName: string;
    password: string;
    company?: string;
  }): Observable<User> {
    return this.http.post<User>(environment.api + '/user/admin', admin);
  }

  deleteAdmin(admin: { email: string }): Observable<User> {
    return this.http.delete<User>(environment.api + '/user', { body: admin });
  }

  getAdminById(id: number): Observable<User> {
    return this.http.get<User>(environment.api + '/user/' + id);
  }

  updateAdmin(admin: User): Observable<User> {
    return this.http.post<User>(environment.api + '/user/admin/update', admin);
  }
