import { ToolchainService, normalizeToolUrl } from './toolchain.service';

/** fake DocPouch client with tool documents and structures */
function fakeClient(toolDocuments: any[], structures: any[]) {
  return {
    fetchDocuments: jest.fn().mockResolvedValue(toolDocuments),
    getStructures: jest.fn().mockResolvedValue(structures),
  } as any;
}

function service(config: any) {
  const authService: any = { getConfig: () => ({ mode: 'oidc', ...config }) };
  return new ToolchainService(authService, {} as any);
}

const tdd = (url: string, structureId: string, type = 7, subType = 0, name = 'Peer Grading') => ({
  content: { name, url, assignments: { peerGradingResult: { structureId, type, subType } } },
});

const structures = [
  { _id: 's-tm', name: 'Peer Grading Result', type: 7, subType: 0 },
  { _id: 's-dev', name: 'Peer Grading Result', type: 100, subType: 0 },
  { _id: 's-evil', name: 'Evil', type: 5, subType: 0 },
];

describe('normalizeToolUrl', () => {
  it.each([
    ['https://Host.ch/tc/PeerGrading/', 'https://host.ch/tc/PeerGrading'],
    ['https://host.ch/tc/PeerGrading/de/', 'https://host.ch/tc/PeerGrading'],
    ['https://host.ch/tc/PeerGrading/en', 'https://host.ch/tc/PeerGrading'],
    ['https://host.ch/tc/PeerGrading?x=1#y', 'https://host.ch/tc/PeerGrading'],
    ['not a url', ''],
    [undefined, ''],
  ])('%p -> %p', (input, expected) => {
    expect(normalizeToolUrl(input as any)).toBe(expected);
  });
});

describe('ToolchainService.resolveTarget', () => {
  const own = 'https://host.ch/tc/PeerGrading';

  it('1. configured structure id has priority', async () => {
    const s = service({ publicUrl: own, resultStructureId: 's-dev' });
    const target = await s.resolveTarget(fakeClient([tdd(own, 's-tm')], structures));
    expect(target).toEqual({ structureId: 's-dev', type: 100, subType: 0 });
  });

  it('2. finds the Tool Details Document by url, also when renamed', async () => {
    const s = service({ publicUrl: own });
    const docs = [tdd(own + '/', 's-tm', 7, 0, 'Peer Grading BFH')];
    const target = await s.resolveTarget(fakeClient(docs, structures));
    // type/subType from the assignment, not 100/0
    expect(target).toEqual({ structureId: 's-tm', type: 7, subType: 0 });
  });

  it('ignores a document with the right name but another url', async () => {
    const s = service({ publicUrl: own });
    const docs = [tdd('https://evil.example/', 's-evil', 5, 0, 'Peer Grading')];
    await expect(s.resolveTarget(fakeClient(docs, structures))).rejects.toThrow(
      'PGT_RESULT_STRUCTURE_MISSING'
    );
  });

  it('refuses to guess when several documents claim this url', async () => {
    const s = service({ publicUrl: own });
    const docs = [tdd(own, 's-tm'), tdd(own, 's-evil', 5)];
    await expect(s.resolveTarget(fakeClient(docs, structures))).rejects.toThrow(
      'PGT_TOOL_DOCUMENT_AMBIGUOUS'
    );
  });

  it('3. name fallback only when allowed (development)', async () => {
    const dev = service({ publicUrl: own, allowStructureNameFallback: true });
    const target = await dev.resolveTarget(fakeClient([], structures));
    expect(target.structureId).toBe('s-tm');

    const prod = service({ publicUrl: own, allowStructureNameFallback: false });
    await expect(prod.resolveTarget(fakeClient([], structures))).rejects.toThrow(
      'PGT_RESULT_STRUCTURE_MISSING'
    );
  });
});

describe('ToolchainService.buildResult (anonymisation)', () => {
  const peer = (peerId: number, lastName: string) =>
    ({ peerId, firstName: 'X', lastName, email: `${lastName}@example.org` }) as any;

  function campaignWithScores() {
    const peers = [peer(1, 'Aebi'), peer(2, 'Bucher'), peer(3, 'Caflisch')];
    return {
      campaignId: 1,
      name: 'Demo',
      criteria: [{ criteriaId: 1, name: 'Quality', weight: 1 }],
      groups: [{ number: 1, peers, gradings: [] }],
    } as any;
  }

  // score = peerId, so we can see which person ended up as "Peer 1"
  const campaignService: any = {
    getPeersThirdPartyAverageByCriteria: (_c: any, _g: any, p: any) => p.peerId,
    getPeersSelfAverage: (_g: any, p: any) => p.peerId,
    getPeersThirdPartyAverage: (_g: any, p: any) => p.peerId,
  };

  it('contains no names or e-mails', () => {
    const s = new ToolchainService({} as any, campaignService);
    const json = JSON.stringify(s.buildResult(campaignWithScores()));
    expect(json).not.toMatch(/Aebi|Bucher|Caflisch|example\.org/);
    expect(json).toContain('Peer 1');
  });

  it('"Peer 1" is not always the first person of the class list', () => {
    const s = new ToolchainService({} as any, campaignService);
    s.random = () => 0; // shuffle with fixed numbers: order 2, 3, 1
    const rows = s.buildResult(campaignWithScores()).results;
    expect(rows.map((r) => r.peerLabel)).toEqual(['Peer 1', 'Peer 2', 'Peer 3']);
    expect(rows[0].weightedScore).not.toBe(1); // first in list is not Peer 1
    expect(rows.map((r) => r.weightedScore).sort()).toEqual([1, 2, 3]); // nobody lost
  });

  it('uses crypto random numbers by default', () => {
    const s = new ToolchainService({} as any, campaignService);
    const values = Array.from({ length: 20 }, () => s.random());
    expect(values.every((v) => v >= 0 && v < 1)).toBe(true);
    expect(new Set(values).size).toBeGreaterThan(1);
  });
});

import { Injectable } from '@angular/core';
import DocPouchClient, {
  I_DocumentCreation,
  I_DocumentEntry,
} from 'docpouch-client';
import { Campaign } from '../interfaces';
import { AuthService } from './auth.service';
import { CampaignService } from './campaign.service';

/** DocPouch type/subType pair of the peer grading result structure. */
export const PGT_RESULT_TYPE = 100;
export const PGT_RESULT_SUBTYPE = 0;
export const PGT_RESULT_STRUCTURE_NAME = 'Peer Grading Result';
export const PGT_TOOL_NAME = 'Peer Grading';
/** role key in the manifest and in `assignments` of the Tool Details Document */
export const PGT_RESULT_ROLE = 'peerGradingResult';

export interface PublishTarget {
  structureId: string;
  type: number;
  subType: number;
}

/**
 * Normalises a tool URL for comparison: no trailing slash, no language
 * prefix (/de, /en), no query/hash, lower-case host.
 * "https://Host/tc/PeerGrading/de/" -> "https://host/tc/PeerGrading"
 */
export function normalizeToolUrl(url: string | undefined | null): string {
  if (!url) return '';
  try {
    const u = new URL(url);
    const path = u.pathname
      .replace(/\/+$/, '')
      .replace(/\/(de|en)$/i, '');
    return `${u.protocol}//${u.host.toLowerCase()}${path}`;
  } catch {
    return '';
  }
}

export interface PeerGradingResultRow {
  peerLabel: string;
  groupNumber: number;
  peerCount: number;
  criteriaNames: string[];
  criteriaScores: number[];
  selfScore: number;
  weightedScore: number;
}

export interface PeerGradingResult {
  campaignName: string;
  campaignId: number;
  publishedAt: string;
  results: PeerGradingResultRow[];
}

/**
 * Publishes aggregated, anonymised peer grading results to DocPouch.
 *
 * The document is created as private: only the owner (the signed-in admin)
 * and DocPouch administrators can read it. No names, e-mails or comments are
 * published.
 */
@Injectable({
  providedIn: 'root',
})
export class ToolchainService {
  constructor(
    private authService: AuthService,
    private campaignService: CampaignService
  ) {}

  canPublish(): boolean {
    return this.authService.isOidcMode();
  }

  /** random number 0..1 (crypto); replaceable in tests */
  random: () => number = () =>
    crypto.getRandomValues(new Uint32Array(1))[0] / 2 ** 32;

  /** Fisher-Yates shuffle with crypto random numbers */
  private shuffled<T>(items: T[]): T[] {
    const copy = [...items];
    for (let i = copy.length - 1; i > 0; i--) {
      const j = Math.floor(this.random() * (i + 1));
      [copy[i], copy[j]] = [copy[j], copy[i]];
    }
    return copy;
  }

  /**
   * Builds the anonymised result payload. Peers are replaced by a per-group
   * label ("Peer 1", "Peer 2", ...), never by name or e-mail.
   *
   * The order is shuffled on every publication: otherwise "Peer 1" would be
   * the first person of the class list (usually alphabetical) and anybody
   * who knows the list could assign the results to the students.
   */
  buildResult(campaign: Campaign): PeerGradingResult {
    const results: PeerGradingResultRow[] = [];

    for (const group of campaign.groups) {
      this.shuffled(group.peers).forEach((peer, index) => {
        results.push({
          peerLabel: `Peer ${index + 1}`,
          groupNumber: group.number,
          peerCount: group.peers.length,
          criteriaNames: campaign.criteria.map((criteria) => criteria.name),
          criteriaScores: campaign.criteria.map((criteria) =>
            this.campaignService.getPeersThirdPartyAverageByCriteria(
              criteria,
              group,
              peer
            )
          ),
          selfScore: this.campaignService.getPeersSelfAverage(group, peer),
          weightedScore: this.campaignService.getPeersThirdPartyAverage(
            group,
            peer
          ),
        });
      });
    }

    return {
      campaignName: campaign.name,
      campaignId: campaign.campaignId,
      publishedAt: new Date().toISOString(),
      results,
    };
  }

  /**
   * Creates the private DocPouch document and returns its id.
   */
  async publishCampaign(campaign: Campaign): Promise<string> {
    const client = this.authService.getDocPouchClient();
    if (!client) {
      throw new Error('DOCPOUCH_NOT_AVAILABLE');
    }

    // Refresh the DocPouch token if it is about to expire.
    await client.ensureValidOidcToken();

    const target = await this.resolveTarget(client);
    const result = this.buildResult(campaign);

    // `createDocument` is typed with the full entry (including the
    // server-assigned `_id`/`owner`), but the API only expects the creation
    // payload. The reference Toolchain tools call it the same way.
    const payload: I_DocumentCreation = {
      // type/subType of the assigned structure, not a fixed value: the Tool
      // Manager gives new structures the next free type (not always 100)
      type: target.type,
      subType: target.subType,
      title: `${PGT_TOOL_NAME} — ${campaign.name}`,
      description:
        'Aggregated, anonymised peer grading results. Visible to administrators only.',
      shareWithGroup: false,
      shareWithDepartment: false,
      // Private: owner + DocPouch administrators only.
      public: false,
      content: {
        structureID: target.structureId,
        structuredData: result,
      },
    };

    const document = await client.createDocument(
      payload as unknown as I_DocumentEntry
    );

    return document._id;
  }

  /**
   * Finds the structure (and its type/subType) for the published results:
   *
   * 1. PGT_RESULT_STRUCTURE_ID from the backend configuration (recommended
   *    for production: cannot be redirected by other DocPouch users)
   * 2. the Tool Details Document whose `url` is this installation, role
   *    `peerGradingResult` (the tool name can be renamed in the Tool Manager,
   *    the url not)
   * 3. development only: a structure named "Peer Grading Result"
   */
  async resolveTarget(client: DocPouchClient): Promise<PublishTarget> {
    const config = this.authService.getConfig();
    const structures = await client.getStructures();

    const fromStructure = (id: string): PublishTarget | null => {
      const s = structures.find((candidate) => candidate._id === id);
      return s
        ? {
            structureId: s._id as string,
            type: s.type ?? PGT_RESULT_TYPE,
            subType: s.subType ?? PGT_RESULT_SUBTYPE,
          }
        : null;
    };

    // 1. fixed configuration
    if (config.resultStructureId) {
      const target = fromStructure(config.resultStructureId);
      if (!target) throw new Error('PGT_RESULT_STRUCTURE_NOT_FOUND');
      return target;
    }

    // 2. Tool Details Document of this installation
    const ownUrl = normalizeToolUrl(config.publicUrl || document.baseURI);
    const toolDocuments = await client.fetchDocuments({ type: 0, subType: 0 });
    const matches = toolDocuments.filter(
      (d) =>
        normalizeToolUrl(d.content?.url) === ownUrl &&
        d.content?.assignments?.[PGT_RESULT_ROLE]?.structureId
    );
    if (matches.length > 1) {
      // several documents claim to be this tool: do not guess
      throw new Error('PGT_TOOL_DOCUMENT_AMBIGUOUS');
    }
    if (matches.length === 1) {
      const assignment = matches[0].content.assignments[PGT_RESULT_ROLE];
      const structure = fromStructure(assignment.structureId);
      return {
        structureId: assignment.structureId,
        // the assignment is what the operator chose in the Tool Manager
        type: assignment.type ?? structure?.type ?? PGT_RESULT_TYPE,
        subType: assignment.subType ?? structure?.subType ?? PGT_RESULT_SUBTYPE,
      };
    }

    // 3. development fallback
    if (config.allowStructureNameFallback) {
      const s = structures.find((c) => c.name === PGT_RESULT_STRUCTURE_NAME);
      if (s?._id) return fromStructure(s._id) as PublishTarget;
    }

    throw new Error('PGT_RESULT_STRUCTURE_MISSING');
  }
}

import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { map, Observable, switchMap } from 'rxjs';
import { environment } from '../../environments/environment';
import { User, Campaign, UserRole, RegisterData } from '../interfaces';
import { SnackBarService } from './snack-bar.service';
import { CampaignService } from './campaign.service';
import { TokenService } from './token.service';
import { Router } from '@angular/router';

/**
 * this service handles data transactions regarding users
 */
@Injectable({
  providedIn: 'root',
})
export class UserService {
  constructor(
    private http: HttpClient,
    private tokenService: TokenService,
    private snackBarService: SnackBarService,
    private router: Router,
    private campaignService: CampaignService
  ) {}

  /**
   * this functions sets a users password
   * @param data
   * @returns
   */
  changeUserPW(data: any) {
    return this.http.post(environment.api + '/user/admin/pw', data);
  }

  getUser(): Observable<User> {
    return this.http
      .get(environment.api + '/auth/profile')
      .pipe(map((user: any) => this.cleanupUserData(user)));
  }

  login(data: any, returnUrl?: string) {
    const targetUrl = returnUrl ?? '/admin-dashboard';
    data.email = data.email.trim();
    return this.http
      .post(environment.api + '/auth/login', data)
      .pipe(
        switchMap((tokens: any) => {
          // the refresh token comes as HttpOnly cookie
          this.tokenService.setAccessToken(tokens.accessToken);
          return this.getUser();
        })
      )
      .subscribe({
        next: (user: User) => {
          // get return url from query parameters or default to home page
          if (user.roles.includes(UserRole.ADMIN)) {
            this.router.navigateByUrl(targetUrl);
          } else {
            this.snackBarService.openSnackBar(
              $localize`Zugriff nur für Administratoren gestattet`
            );
          }
          return;
        },
        error: (error) => {
          this.snackBarService.openSnackBar(
            $localize`Username oder Passwort falsch`
          );
        },
      });
  }

  logout() {
    this.http
      .post(environment.api + '/auth/logout', this.tokenService.getToken())
      .subscribe()
      .add(() => {
        this.tokenService.signOut();
        this.router.navigate(['./login']);
      });
  }

  cleanupUserData(user: User): User {
    let { roles, campaigns, ...rest } = user;
    let cleanRoles: any[] = [];
    for (let role of user.roles) {
      cleanRoles.push(UserRole[role]);
    }
    let cleanCampaigns: Campaign[] = [];
    if (user.campaigns) {
      for (let campaign of user.campaigns) {
        cleanCampaigns.push(this.campaignService.cleanupCampaignData(campaign));
      }
    }
    return {
      ...rest,
      roles: cleanRoles,
      campaigns: cleanCampaigns,
    };
  }

  register(registerData: RegisterData) {
    registerData.email = registerData.email.trim();
    registerData.emailRepeat = registerData.emailRepeat.trim();
    registerData.company = registerData.company?.trim();

    return this.http.post(environment.api + '/auth/register', registerData);
  }

  confirmEmail(registerToken: string) {
    return this.http.post(environment.api + '/auth/confirm-email', {
      registerToken: registerToken,
    });
  }

  /**
   * this function is used in the header component to get a string of all the users roles
   * @param user
   * @returns
   */
  userRolesToString(user: User) {
    let result: string[] = [];
    for (let role of user.roles) {
      if (role == 0) {
        result.push($localize`Admin`);
      } else if (role == 2) {
        result.push($localize`Super User*in`);
      } else {
        result.push($localize`Teilnehmer*in`);
      }
    }
    return result;
  }
}

